  function renderBag(){const dictionary=languages[locale];document.getElementById('cartCount').textContent=bag.reduce((sum,item)=>sum+item.quantity,0);document.getElementById('bagSubtotal').textContent='$'+bag.reduce((sum,item)=>sum+item.quantity*item.price,0).toFixed(2);document.getElementById('bagItems').innerHTML=bag.length?bag.map((item,index)=>`<article class="cart-item"><a href="product.html"><img src="${escape(item.image)}" alt="${escape(item.name)}"></a><div><h3><a href="product.html">${escape(item.name)}</a></h3><p>${escape(item.variant||'')} · $${item.price.toFixed(2)}</p><div class="cart-quantity"><button data-cart-action="minus" data-index="${index}" aria-label="Decrease ${escape(item.name)} quantity">−</button><span>${item.quantity}</span><button data-cart-action="plus" data-index="${index}" aria-label="Increase ${escape(item.name)} quantity">+</button><button class="cart-remove" data-cart-action="remove" data-index="${index}">${locale==='zh'?'移除':'Remove'}</button></div></div></article>`).join(''):`<p class="cart-empty">${dictionary.empty}</p>`;}
