  document.addEventListener('click',event=>{const button=event.target.closest('[data-add-cart]');if(!button)return;const name=button.dataset.product||'Collagen Hair Mask';const isMainPurchase=Boolean(button.closest('.purchase-row,.product-info'));const variant=isMainPurchase?(document.querySelector('.size.is-active')?.textContent.trim()||''):'';const quantity=isMainPurchase?Math.max(1,Math.floor(Number(document.getElementById('qty')?.value)||1)):1;const price=Number(button.dataset.price)||(/oil/i.test(name)?38.99:/shampoo|conditioner/i.test(name)?88:/500/.test(variant)?24.99:15.99);const image=/oil/i.test(name)?'assets/essential-3.jpg':/conditioner/i.test(name)?'assets/essential-4.jpg':/shampoo/i.test(name)?'assets/essential-2.jpg':'assets/editor-1.jpg';const id=name+'|'+variant;const item=bag.find(item=>item.id===id);if(item)item.quantity+=quantity;else bag.push({id,name,variant,price,quantity,image});save(cartKey,bag);renderBag();if(bagPanel.hidden)toggleUtility(bagPanel,bagToggle);const feedback=document.getElementById('cartFeedback');feedback.textContent=locale==='zh'?`${name} 已加入购物袋`:`${name} added to your bag.`;feedback.classList.add('is-visible');clearTimeout(feedbackTimer);feedbackTimer=setTimeout(()=>feedback.classList.remove('is-visible'),2200);});
